import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const styles = {
  // --- CHANGES START HERE ---
  footer: {
    // Using the same dark background as the header
    backgroundColor: '#1a202c', 
    color: '#a0aec0', // Default text color for copyright
    padding: '30px 20px', // Increased padding slightly for better spacing
    textAlign: 'center',
    borderTop: '1px solid #2d3748', // Added a top border for separation
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  nav: {
    marginBottom: '20px',
  },
  footerLink: {
    // Brighter link color for better contrast, same as header nav
    color: '#e2e8f0', 
    textDecoration: 'none',
    margin: '0 15px',
    fontSize: '1rem',
    transition: 'color 0.3s ease', // Smooth transition for hover effect
  },
  // Style for the link on hover
  footerLinkHover: {
    color: '#a7ffeb', // Highlight color, same as header title
  },
  // --- CHANGES END HERE ---
  copyright: {
    marginTop: '16px',
    fontSize: '0.9rem',
    color: '#a0aec0', // Explicitly set copyright color to be less prominent
  }
};

const Footer = () => {
  const [hoveredLink, setHoveredLink] = useState(null);

  const handleMouseEnter = (linkName) => {
    setHoveredLink(linkName);
  };

  const handleMouseLeave = () => {
    setHoveredLink(null);
  };

  // Array of footer links for easier management
  const footerLinks = [
    { text: 'Home', path: '/', isRouterLink: true },
    { text: 'About Us', path: '/about', isRouterLink: true },
    { text: 'Services', path: '/#services', isRouterLink: false },
    { text: 'Contact Us', path: '/#contact', isRouterLink: false },
    { text: 'Terms and Conditions', path: '/terms', isRouterLink: true },
  ];

  return (
    <footer style={styles.footer}>
      <div style={styles.container}>
        <nav style={styles.nav}>
          {footerLinks.map(({ text, path, isRouterLink }) => 
            isRouterLink ? (
              <Link
                key={text}
                to={path}
                style={{
                  ...styles.footerLink,
                  ...(hoveredLink === text ? styles.footerLinkHover : {}),
                }}
                onMouseEnter={() => handleMouseEnter(text)}
                onMouseLeave={handleMouseLeave}
              >
                {text}
              </Link>
            ) : (
              <a
                key={text}
                href={path}
                style={{
                  ...styles.footerLink,
                  ...(hoveredLink === text ? styles.footerLinkHover : {}),
                }}
                onMouseEnter={() => handleMouseEnter(text)}
                onMouseLeave={handleMouseLeave}
              >
                {text}
              </a>
            )
          )}
        </nav>
        <p style={styles.copyright}>
          &copy; {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
        </p>
      </div>
    </footer>
  );
};

export default Footer;
